import java.io.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.text.Normalizer;
import java.util.*;
import java.util.regex.*;

/**
 * Secure file serving module with Unicode-aware filename handling.
 * Supports internationalized filenames per RFC 5987.
 */
public class SecureFileServer {

    private static final String BASE_DIR = "/var/www/data/public";
    private static final Pattern SAFE_CHARS = Pattern.compile("^[\\p{L}\\p{N}][\\p{L}\\p{N}._\\- ]{0,200}$");
    private static final Set<String> ALLOWED_EXTENSIONS = Set.of(".txt", ".pdf", ".png", ".jpg", ".csv");

    /**
     * Validates that a filename is safe for filesystem access.
     * Checks for traversal sequences, null bytes, and restricted characters.
     */
    private boolean isValidFilename(String filename) {
        if (filename == null || filename.isEmpty()) return false;
        if (filename.length() > 255) return false;

        // Check for null bytes
        if (filename.indexOf('\0') >= 0) return false;

        // Reject path separators
        if (filename.contains("/") || filename.contains("\\")) return false;

        // Reject traversal
        if (filename.contains("..")) return false;

        // Must match safe character pattern (Unicode letters/numbers plus ._- space)
        if (!SAFE_CHARS.matcher(filename).matches()) return false;

        // Must have allowed extension
        String lower = filename.toLowerCase();
        boolean hasValidExt = ALLOWED_EXTENSIONS.stream().anyMatch(lower::endsWith);
        if (!hasValidExt) return false;

        return true;
    }

    /**
     * Normalizes Unicode to NFC form for consistent filesystem access.
     * This ensures that equivalent Unicode representations map to the same file.
     * For example, 'ñ' (U+00F1) and 'n' + combining tilde (U+006E U+0303)
     * should resolve to the same file.
     */
    private String normalizeUnicode(String input) {
        return Normalizer.normalize(input, Normalizer.Form.NFC);
    }

    /**
     * Resolves the file path securely within the base directory.
     * Uses Path.normalize() to resolve any remaining . or .. components,
     * then verifies the result is within BASE_DIR.
     */
    private Path resolveSecurePath(String filename) throws SecurityException {
        Path basePath = Paths.get(BASE_DIR).toAbsolutePath().normalize();
        Path filePath = basePath.resolve(filename).normalize();

        if (!filePath.startsWith(basePath)) {
            throw new SecurityException("Path traversal detected: " + filename);
        }

        return filePath;
    }

    /**
     * Serves a file to the client after security validation.
     * 
     * Processing order:
     * 1. Normalize Unicode for consistent handling
     * 2. Validate the normalized filename for dangerous patterns
     * 3. Resolve and verify path is within base directory
     */
    public byte[] serveFile(String requestedFilename) throws IOException {
        // Step 1: Unicode normalization FIRST for consistent validation
        String normalized = normalizeUnicode(requestedFilename);

        // Step 2: Validate the normalized filename
        if (!isValidFilename(normalized)) {
            throw new SecurityException("Invalid filename: rejected by validation");
        }

        // Step 3: Resolve path securely
        Path securePath = resolveSecurePath(normalized);

        // Step 4: Read and return file
        if (!Files.exists(securePath)) {
            throw new FileNotFoundException("File not found: " + securePath.getFileName());
        }

        if (Files.size(securePath) > 10_000_000) {
            throw new IOException("File too large");
        }

        return Files.readAllBytes(securePath);
    }

    /**
     * Lists files available in a subdirectory.
     * Subdirectory name follows same validation rules.
     */
    public List<String> listFiles(String subdirectory) throws IOException {
        // Normalize first, then validate
        String normalizedDir = subdirectory != null ? normalizeUnicode(subdirectory) : "";

        if (normalizedDir != null && !normalizedDir.isEmpty()) {
            if (!isValidFilename(normalizedDir + ".txt")) { // append ext for validation
                throw new SecurityException("Invalid subdirectory name");
            }
        }

        Path dirPath = resolveSecurePath(normalizedDir);

        if (!Files.isDirectory(dirPath)) {
            throw new FileNotFoundException("Directory not found");
        }

        List<String> results = new ArrayList<>();
        try (DirectoryStream<Path> stream = Files.newDirectoryStream(dirPath)) {
            for (Path entry : stream) {
                if (Files.isRegularFile(entry)) {
                    results.add(entry.getFileName().toString());
                }
            }
        }
        return results;
    }
}
